def w3(n):
    h, r = divmod(n, 100); t, o = divmod(r, 10)
    s = ''
    if h: s += ('' if h == 1 else ONES[h] + ' ') + 'yüz '
    s += (TENS[t] + ' ' if t else '') + (ONES[o] if o else '')
    return s.strip()

def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    parts = []
    for val, name in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append(name if (val == 1000 and q == 1) else w3(q) + ' ' + name)
    if n: parts.append(w3(n))
    return ' '.join(parts)

def money(x, cur):
    x = round(abs(float(x)) + 1e-9, 2)
    whole = int(x); cents = int(round((x - whole) * 100))
    unit, sub = CUR[cur]['unit'], CUR[cur]['sub']
    s = words(whole) + ' ' + unit
    if cents: s += ' ' + words(cents) + ' ' + sub
    return s

