        t = t.replace(a, b)
    return re.sub(r'[^a-z0-9 ]', ' ', t)

def flat(prefix, obj, out):
    if isinstance(obj, dict):
        for k, v in obj.items(): flat(prefix + '.' + str(k), v, out)
