    t = low(text); dig = re.sub(r'[^0-9]', '', str(text))
    try:
        if len(dig) < 4: dig = digits_tr(text) or dig
    except Exception: pass
    res = []
    if len(dig) >= 4:
        for i in idx:
            c = cards()[i]; num = re.sub(r'[^0-9*]', '', c['num'])
            if len(dig) >= 15:
                if num[:6] == dig[:6] and num[-4:] == dig[-4:]: res.append(i)
            elif len(dig) >= 6:
                tail = num[-6:]
                if all(a == '*' or a == b for a, b in zip(tail, dig[-6:])): res.append(i)
            elif c['l4'] == dig[-4:]: res.append(i)
        return res, 'digits', dig
    tw = set(t.split())
