        lst = nm[0] if len(nm) == 1 else ', '.join(nm[:-1]) + ' ve ' + nm[-1]
        parts.append(S['clear'].replace('[LIST]', lst))
    if not owe:
        return S['nodebt'].replace('[INTRO]', intro).replace('[SD]', sdate(b['statementDate'])).replace('[TOTAL]', money(max(fnum(b.get('TL.totalDebt')) or 0, 0), 'TL')).replace('[DUE]', sdate(b.get('lastPayDate')))
    passed = lp is not None and today > lp
