        ra = fnum(b.get('TL.remainAutomaticPaymentAmount')) or 0
        if ra > 0: parts.append(S['auto'].replace('[AMT]', money(ra, 'TL')))
    if lp == today: parts.append(S['due_today'])
    elif passed:
        tot = fnum(b.get('TL.totalDebt')) or 0
        parts.append(S['due_passed'].replace('[DUE]', sdate(b.get('lastPayDate'))).replace('[TOTAL]', money(max(tot, 0), 'TL')))
